script:
let a = arch();
let targets = ["pthread_create", "abort", "kill", "raise", "_exit", "exit"];
for t in targets {
  let syms = find_symbols(t);
  for s in syms {
    if s.name == t || s.name.ends_with("::" + t) {
      let xrefs = get_xrefs(s.address);
      for x in xrefs {
        let sev = if t == "pthread_create" { "INFO" } else { "HIGH" };
        let desc = if x.caller != "" { x.caller + " -> " + x.instruction } else { x.instruction };
        let can_nop = false;
        if t == "kill" || t == "raise" || t == "_exit" || t == "exit" {
          let after = disasm(x.from + 4, 44);
          for ins in after {
            if ins.mnemonic == "ret" || ins.mnemonic == "b" || ins.mnemonic == "jmp" || (ins.mnemonic == "bx" && ins.op_str == "lr") || (ins.mnemonic == "pop" && ins.op_str.contains("pc")) {
              can_nop = true;
              break;
            }
            if (ins.mnemonic == "stp" && ins.op_str.contains("x29")) || (ins.mnemonic == "push" && (ins.op_str == "rbp" || ins.op_str == "ebp" || ins.op_str.contains("lr"))) {
              break;
            }
          }
        }
        if can_nop {
          report_patch("Calls " + t, x.from, sev, desc, "quick", "nop");
        } else {
          report("Calls " + t, x.from, sev, desc);
        }
        if t == "pthread_create" && x.from > 48 {
          let win = disasm(x.from - 48, 48);
          let adrp_x2 = -1;
          let pc_deltas = #{};
          for ins in win {
            if a == "aarch64" && ins.mnemonic == "adrp" && ins.op_str.starts_with("x2,") {
              adrp_x2 = parse_addr(ins.op_str);
            } else if a == "aarch64" && adrp_x2 > 0 && ins.mnemonic == "add" && ins.op_str.starts_with("x2, x2,") {
              let off = parse_addr(ins.op_str);
              if off >= 0 {
                report_patch("Watchdog Thread Entry", adrp_x2 + off, "HIGH", "Thread start_routine (adrp+add) passed to pthread_create at " + hex(x.from), "quick", "ret_void");
              }
              adrp_x2 = -1;
            } else if a == "arm" && ins.mnemonic.starts_with("ldr") && ins.op_str.contains("[pc,") {
              let parts = ins.op_str.split(",");
              let reg = parts[0];
              reg.trim();
              let off = parse_addr(ins.op_str);
              if off >= 0 {
                let pc_base = if ins.thumb { (ins.address + 4) & -4 } else { ins.address + 8 };
                let val = read_u32(pc_base + off);
                if val >= 0 {
                  pc_deltas[reg] = if val > 2147483647 { val - 4294967296 } else { val };
                }
              }
            } else if a == "arm" && ins.mnemonic == "add" && ins.op_str.starts_with("r2, pc") {
              let parts = ins.op_str.split(",");
              let src_reg = if parts.len() >= 3 { parts[2] } else { "r2" };
              src_reg.trim();
              if pc_deltas.contains(src_reg) {
                let pc_val = if ins.thumb { ins.address + 4 } else { ins.address + 8 };
                let fn_addr = pc_val + pc_deltas[src_reg];
                if fn_addr > 0 {
                  report_patch("Watchdog Thread Entry", fn_addr, "HIGH", "Thread start_routine (PIC) passed to pthread_create at " + hex(x.from), "quick", "ret_void");
                }
              }
            } else {
              let is_entry = (a == "aarch64" && ins.mnemonic == "adr" && ins.op_str.starts_with("x2,")) || (a == "x86_64" && ins.mnemonic == "lea" && ins.op_str.starts_with("rdx,")) || (a == "arm" && (ins.mnemonic == "adr" || ins.mnemonic == "add") && ins.op_str.starts_with("r2,"));
              if is_entry {
                let fn_addr = parse_addr(ins.op_str);
                if fn_addr > 0 {
                  report_patch("Watchdog Thread Entry", fn_addr, "HIGH", "Thread start_routine passed to pthread_create at " + hex(x.from), "quick", "ret_void");
                }
              }
            }
          }
        }
      }
    }
  }
}
